import {exampleStories,storyCard} from './study-visuals.js';
import {valuationDefaults,valuationExamples,valuationForm,valuationView} from './valuation.js';
import {tvm,convert,npv,examples} from './finance.js';
const $=s=>document.querySelector(s);
const fmt=(x,d=2)=>new Intl.NumberFormat('ko-KR',{maximumFractionDigits:d,minimumFractionDigits:d}).format(Math.abs(x)<1e-10?0:x);
const pct=x=>fmt(x*100,6).replace(/0+$/,'').replace(/\.$/,'');
const raw=x=>Number(x.toPrecision(13)).toString();
const modes={tvm:{index:'01',title:'화폐의 시간가치',tag:'TVM',name:'TVM',sub:'현재가치 · 미래가치',icon:'◷'},monthly:{index:'02',title:'월복리와 월 납입',tag:'MONTHLY',name:'월복리',sub:'월 이율 · 연금 계산',icon:'↻'},apr:{index:'03',title:'명목이율과 실효이율',tag:'APR / EAR',name:'APR · EAR',sub:'연 이율의 올바른 비교',icon:'%'},npv:{index:'04',title:'순현재가치',tag:'NPV',name:'NPV',sub:'현금흐름 · 투자 판단',icon:'≋'}};
Object.assign(modes,{bond:{index:'05',title:'채권 가격과 만기수익률',tag:'BOND',name:'채권',sub:'가격 · YTM · 이자율위험',icon:'◇'},stock:{index:'06',title:'배당성장과 주식 가치평가',tag:'EQUITY',name:'주식 가치',sub:'배당 · 성장률 · PER',icon:'↗'}});
examples.push(...valuationExamples);
const defaults={tvm:{...examples[0].data},monthly:{...examples[3].data},apr:{...examples[5].data},npv:structuredClone(examples[7].data)};
Object.assign(defaults,valuationDefaults);
let mode='tvm',states=structuredClone(defaults),selectedExample='pv',lastResult=null;
const unitName=()=>({won:'원',man:'만원',dollar:'달러'}[states[mode].unit]||'원');
const option=(value,label,selected)=>`<option value="${value}" ${String(value)===String(selected)?'selected':''}>${label}</option>`;
const select=(key,label,opts,hint='')=>`<label class="field" for="${key}"><span class="field-label">${label}</span><select id="${key}" name="${key}">${opts.map(([v,l])=>option(v,l,states[mode][key])).join('')}</select>${hint?`<p class="field-hint">${hint}</p>`:''}</label>`;
function number(key,label,unit='',hint='',disabled=false,value=states[mode][key]){return `<label class="field" for="${key}"><span class="field-label">${label}${disabled?'<b>계산할 값</b>':''}</span><span class="input-wrap" style="display:block"><input id="${key}" name="${key}" type="text" inputmode="decimal" value="${disabled?'':value}" ${disabled?'disabled placeholder="자동 계산"':''} autocomplete="off" spellcheck="false" aria-describedby="hint-${key}"><span class="input-unit">${unit}</span></span><p class="field-hint" id="hint-${key}">${hint}</p></label>`;}
const unitSelect=()=>select('unit','금액 단위',[['won','원 (KRW)'],['man','만원'],['dollar','달러 (USD)']],'단위만 변경 · 환율 변환 없음');
const freqOptions=[[1,'연 1회'],[2,'반기 · 연 2회'],[4,'분기 · 연 4회'],[12,'매월 · 연 12회'],[365,'매일 · 연 365회']];
function renderNav(){
 $('#navigation').innerHTML=Object.entries(modes).map(([id,m])=>`<button type="button" class="nav-item ${mode===id?'active':''}" data-mode="${id}" aria-pressed="${mode===id}"><span class="nav-icon" aria-hidden="true">${m.icon}</span><span><strong>${m.name}</strong><small>${m.sub}</small></span></button>`).join('');
 $('#mobile-navigation').innerHTML=Object.entries(modes).map(([id,m])=>`<button type="button" class="mobile-tab ${mode===id?'active':''}" data-mode="${id}" aria-pressed="${mode===id}">${m.name}</button>`).join('');
}
function renderForm(){
 const s=states[mode];
 if(['bond','stock'].includes(mode)){$('#fields').innerHTML=valuationForm(mode,s,{select,number,unitSelect,freqOptions});return;}
 if(mode==='tvm'||mode==='monthly'){
 const monthly=mode==='monthly';
 $('#fields').innerHTML=`<div class="form-grid">${select('solve','구할 값',[['pv','PV · 현재가치'],['fv','FV · 미래가치'],['pmt','PMT · 정기 지급액'],['n','N · 총 기간'],['rate','I/Y · 연 명목이율']])}${unitSelect()}</div><div class="form-grid">${number('n','기간',s.nUnit==='years'?'년':s.nUnit==='months'?'개월':'회','N은 아래에서 전체 횟수로 환산',s.solve==='n')}${select('nUnit','기간의 단위',[['years','년'],['months','개월'],['periods','납입 기간 수 (N)']])}${number('rate',s.solve==='rate'?'연 명목이율 I/Y':'이율','%','12%라면 12 입력',s.solve==='rate')}${select('rateType','입력한 이율의 기준',[['nominal','연 명목이율 (APR)'],['effective','연 실효이율 (EAR)'],['period','납입 한 기간의 이율']],s.solve==='rate'?'역산 결과는 연 명목이율':'선택한 기준으로 기간 이율을 환산')}${number('pv','PV · 현재가치',unitName(),'투자 지출 − / 대출 수령 +',s.solve==='pv')}${number('pmt','PMT · 매회 지급액',unitName(),'매회 납입 − / 수령 +',s.solve==='pmt')}${number('fv','FV · 미래가치',unitName(),'미래 수령 + / 잔액 목표',s.solve==='fv')}</div><div class="form-divider"></div><div class="settings-label"><span>빈도와 현금흐름 시점</span><button type="button" class="inline-help" data-help>P/Y · C/Y 차이 ?</button></div><div class="frequency-grid">${monthly?`<label class="field"><span class="field-label">P/Y · 연 납입 횟수</span><select disabled aria-label="P/Y 월 12회"><option>12 · 매월</option></select></label><label class="field"><span class="field-label">C/Y · 연 복리 횟수</span><select disabled aria-label="C/Y 월 12회"><option>12 · 월복리</option></select></label>`:select('py','P/Y · 연 납입 횟수',freqOptions)+select('cy','C/Y · 연 복리 횟수',freqOptions)}</div><div class="timing-group" role="group" aria-label="지급 시점"><button type="button" data-timing="end" class="${s.bgn?'':'active'}" aria-pressed="${!s.bgn}">END · 매 기간 말</button><button type="button" data-timing="bgn" class="${s.bgn?'active':''}" aria-pressed="${s.bgn}">BGN · 매 기간 초</button></div>`;
 } else if(mode==='apr'){
 $('#fields').innerHTML=select('direction','환산 방향',[['nominal','APR → EAR · 명목에서 실효로'],['effective','EAR → APR · 실효에서 명목으로']])+number('rate',s.direction==='nominal'?'NOM · 연 명목이율 APR':'EFF · 연 실효이율 EAR','%','12%라면 12 입력')+select('cy','C/Y · 연 복리 횟수',freqOptions)+`<div class="help-callout"><strong>같은 연 12%라도 결과는 다릅니다.</strong><p>이자가 원금에 더해지는 횟수가 늘면 실효이율도 달라집니다. EFF로 연간 수익률을 비교해 보세요.</p></div><p class="insight-small">APR은 수수료를 제외한 연 명목이율입니다. 금융상품의 수수료 포함 공시 APR과 구분합니다.</p>`;
 } else {
 $('#fields').innerHTML=`<div class="form-grid">${unitSelect()}${select('py','현금흐름 간격',[[1,'매년 말'],[12,'매월 말']])}${number('rate','할인율','%','현금흐름 간격에 맞춰 환산합니다.')}${select('rateType','할인율의 기준',[['period','현금흐름 한 기간 이율'],['nominal','연 명목이율 (APR)'],['effective','연 실효이율 (EAR)']])}</div>${s.rateType==='nominal'?select('cy','C/Y · 할인율의 연 복리 횟수',freqOptions):''}${number('cf0','CF₀ · 초기 현금흐름',unitName(),'현재 투자 지출은 음수 (−)')}<div class="form-divider"></div><div class="flow-heading"><span>이후 현금흐름 C</span><span>반복 F</span><span></span></div><div id="flow-rows">${s.flows.map((f,j)=>`<div class="flow-row"><div><label class="input-wrap" style="display:block"><input type="text" inputmode="decimal" name="flow-${j}" aria-label="C${j+1} 현금흐름" value="${f.amount}"><span class="input-unit">${unitName()}</span></label><div class="cash-label">C${String(j+1).padStart(2,'0')}</div></div><label><input class="frequency" type="text" inputmode="numeric" name="freq-${j}" aria-label="F${j+1} 반복 횟수" value="${f.frequency}"><span class="cash-label" style="display:block">연속 횟수</span></label><button class="remove-flow" data-remove="${j}" type="button" aria-label="C${j+1} 삭제" ${s.flows.length===1?'disabled':''}>×</button></div>`).join('')}</div><button class="add-flow" type="button" id="add-flow" ${s.flows.length>=24?'disabled':''}>+ 현금흐름 추가 <span style="opacity:.6">(${s.flows.length}/24)</span></button>`;
 }
}
function numberValue(value){const clean=value.replaceAll(',','').replaceAll('−','-').trim();if(clean==='')return NaN;return Number(clean);}
function readForm(){const s=states[mode];for(const el of $('#input-form').elements){if(!el.name||el.disabled)continue;const k=el.name;if(k.startsWith('flow-'))s.flows[+k.split('-')[1]].amount=numberValue(el.value);else if(k.startsWith('freq-'))s.flows[+k.split('-')[1]].frequency=numberValue(el.value);else if(['solve','unit','nUnit','rateType','direction','model','bondSolve','growths'].includes(k))s[k]=el.value;else s[k]=numberValue(el.value);}}
function tvmInput(s){const n=s.nUnit==='years'?s.n*s.py:s.nUnit==='months'?s.n*s.py/12:s.n;return {...s,n,rate:s.rate/100};}
function metric(label,value,unit=''){return `<div><div class="metric-label">${label}</div><div class="metric-value">${value}<span class="metric-unit">${unit}</span></div></div>`;}
const commonHead=(tag)=>`<div class="result-eyebrow"><span>YOUR RESULT</span><span class="result-pill">${tag}</span></div>`;
function timeline(r,s){let n=r.n;const pv=s.solve==='pv'?r.result:s.pv,pmt=s.solve==='pmt'?r.result:s.pmt,fv=s.solve==='fv'?r.result:s.fv;return `<div class="result-section-label">CASH FLOW TIMELINE</div><svg class="timeline-svg" viewBox="0 0 360 110" role="img" aria-label="현재 PV ${fmt(pv)}, 매회 PMT ${fmt(pmt)}, ${fmt(n,2)}기간 후 FV ${fmt(fv)}"><line x1="15" y1="57" x2="345" y2="57" stroke="#547560"/><g fill="#aac29e" font-family="sans-serif" font-size="9"><text x="19" y="92">t = 0</text><text x="172" y="92" text-anchor="middle">${s.bgn?'BGN · 초':'END · 말'}</text><text x="340" y="92" text-anchor="end">N = ${fmt(n,2)}</text></g><g fill="#d3e8ba"><circle cx="25" cy="57" r="4"/><circle cx="335" cy="57" r="4"/></g><g stroke="#72946c" stroke-dasharray="2 3"><line x1="25" y1="28" x2="25" y2="51"/><line x1="335" y1="28" x2="335" y2="51"/></g><g font-family="sans-serif" font-size="10" fill="#d5e7c7"><text x="20" y="20">PV ${fmt(pv)}</text><text x="340" y="20" text-anchor="end">FV ${fmt(fv)}</text><text x="180" y="46" text-anchor="middle">PMT ${fmt(pmt)}</text></g><path d="M80 53v8m50-8v8m50-8v8m50-8v8m50-8v8" stroke="#65885e"/></svg>`;}
function renderResult(){
 const s=states[mode];try {
 let r;
 if(['bond','stock'].includes(mode)){const v=valuationView(mode,s,{fmt,pct,metric,commonHead,step,keys,unitName});$('#result-panel').innerHTML=v.result;$('#key-guide').innerHTML=v.guide;$('#interpretation').innerHTML=v.insight;return;}
 if(mode==='tvm'||mode==='monthly'){
 r=tvm(tvmInput(s));lastResult=r;
 const name={pv:'PV · 현재가치',fv:'FV · 미래가치',pmt:'PMT · 매회 지급액',n:'N · 전체 납입 기간 수',rate:'I/Y · 연 명목이율'}[s.solve];
 const amount=s.solve==='rate'?pct(r.result):fmt(r.result),unit=s.solve==='rate'?'%':s.solve==='n'?'회':unitName();
 $('#result-panel').innerHTML=commonHead(s.bgn?'BEGINNING':'END OF PERIOD')+`<div class="result-name">${name}</div><div class="result-number" data-result="${r.result}">${amount}<span class="result-unit">${unit}</span></div><p class="result-subtitle">${s.solve==='n'?`${fmt(r.n/s.py,4)}년 · ${fmt(r.n/s.py*12,2)}개월`:s.solve==='rate'?'BA II Plus의 I/Y에 해당하는 연 명목이율':r.result<0?'음수는 내 지갑에서 나가는 현금흐름입니다.':'양수는 내 지갑으로 들어오는 현금흐름입니다.'}</p><div class="result-metrics">${metric('전체 기간 N',fmt(r.n,2),'회')}${metric('한 기간 이율',pct(r.i),'%')}${metric('연 실효이율 EAR',pct(r.ear),'%')}</div>${timeline(r,s)}<div class="result-foot"><span>→</span><div>${s.solve==='rate'?`P/Y ${s.py} · C/Y ${s.cy} 기준 역산 결과입니다.`:`계산기 입력: N = ${raw(r.n)} · I/Y = ${pct(r.nominal)}<br>P/Y = ${s.py} · C/Y = ${s.cy} · ${s.bgn?'BGN':'END'}`}</div></div>`;
 renderTvmGuide(r,s);renderTvmInsight(r,s);
 }else if(mode==='apr'){
 r=convert(s.rate/100,s.cy,s.direction);lastResult=r;
 const isNom=s.direction==='nominal';
 const max=Math.max(Math.abs(r.nominal),Math.abs(r.ear),.0001);
 $('#result-panel').innerHTML=commonHead('INTEREST CONVERSION')+`<div class="result-name">${isNom?'EFF · 연 실효이율 EAR':'NOM · 연 명목이율 APR'}</div><div class="result-number" data-result="${r.result}">${pct(r.result)}<span class="result-unit">%</span></div><p class="result-subtitle">${s.cy===1?'연 1회 복리에서는 NOM과 EFF가 같습니다.':`연 ${s.cy}회 복리를 반영한 연 이율입니다.`}</p><div class="result-metrics">${metric('연 명목이율 NOM',pct(r.nominal),'%')}${metric('복리 한 기간 이율',pct(r.period),'%')}${metric('연 복리 C/Y',s.cy,'회')}</div><div class="comparison-bars"><div class="comparison-row"><div class="comparison-caption"><span>NOM · 명목</span><span>${pct(r.nominal)}%</span></div><div class="comparison-track"><div class="comparison-fill" style="width:${Math.abs(r.nominal)/max*100}%"></div></div></div><div class="comparison-row"><div class="comparison-caption"><span>EFF · 실효</span><span>${pct(r.ear)}%</span></div><div class="comparison-track"><div class="comparison-fill eff" style="width:${Math.abs(r.ear)/max*100}%"></div></div></div></div><div class="result-foot"><span>→</span><div>EFF − NOM = ${fmt((r.ear-r.nominal)*100,6)}%p<br>1년 동안 복리로 반영되는 차이입니다.${r.nominal<0?'<br>막대 길이는 이율의 절댓값입니다.':''}</div></div>`;
 renderAprGuide(r,s);
 $('#interpretation').innerHTML=`<h4 class="insight-title">${s.cy===1?'복리가 연 1회라면,<br>명목과 실효는 같습니다.':'이율을 비교할 때는,<br>같은 연 실효이율로.'}</h4><p class="insight-copy">연 명목 ${pct(r.nominal)}%를 연 ${s.cy}회 복리로 적용하면, 1년간 실제 변화율은 ${pct(r.ear)}%입니다. 복리 한 기간의 이율은 ${pct(r.period)}%입니다.</p><div class="formula-box">${isNom?'EAR = (1 + APR / m)<sup>m</sup> − 1':'APR = m × [(1 + EAR)<sup>1/m</sup> − 1]'}<br><small>m = C/Y = ${s.cy}</small></div><p class="insight-small">NOM과 EFF는 모두 연 이율입니다. EFF를 단순히 12로 나눠 월 이율로 쓰지 않습니다. 월 이율은 (1 + EAR)<sup>1/12</sup> − 1로 계산합니다.</p><button class="text-button" data-help>P/Y · C/Y · NOM · EFF 도움말 <span>↗</span></button>`;
 }else{
 r=npv({...s,rate:s.rate/100});lastResult=r;
 $('#result-panel').innerHTML=commonHead('NET PRESENT VALUE')+`<div class="result-name">NPV · 순현재가치</div><div class="result-number" data-result="${r.result}">${fmt(r.result)}<span class="result-unit">${unitName()}</span></div><p class="result-subtitle">${Math.abs(r.result)<.005?'현재가치 기준 손익분기 수준입니다.':r.result>0?'요구수익률을 충족하고도 남는 현재가치입니다.':'요구수익률 기준으로 투자 회수가 부족합니다.'}</p><div class="result-metrics">${metric('전체 현금흐름',r.periods,s.py===12?'개월':'년')}${metric('한 기간 할인율 I',pct(r.i),'%')}${metric('미래 CF의 현재가치',fmt(r.inflowPV),unitName())}</div>${npvChart(r,s)}<div class="result-foot"><span>→</span><div>BA II Plus의 NPV 워크시트에 I = ${pct(r.i)} 입력.<br>CF₀는 할인하지 않고 현재가치에 바로 더합니다.</div></div><details class="cf-details"><summary>기간별 할인 계산 펼치기</summary><div class="cf-table-wrap"><table class="cf-table"><thead><tr><th>기간</th><th>현금흐름</th><th>현재가치 (${unitName()})</th></tr></thead><tbody><tr><td>0</td><td>${fmt(s.cf0)}</td><td>${fmt(s.cf0)}</td></tr>${r.rows.slice(0,240).map(row=>`<tr><td>${row.period}</td><td>${fmt(row.amount)}</td><td>${fmt(row.present)}</td></tr>`).join('')}</tbody></table></div>${r.rows.length>240?'<p>처음 240기간을 표시합니다. NPV에는 전체 기간이 반영됩니다.</p>':''}</details>`;
 renderNpvGuide(r,s);
 $('#interpretation').innerHTML=`<h4 class="insight-title">${Math.abs(r.result)<.005?'현재가치 기준,<br>투자와 회수가 균형입니다.':r.result>0?'요구수익률을 넘어,<br>가치가 더해집니다.':'요구수익률에 비해,<br>회수 가치가 부족합니다.'}</h4><p class="insight-copy">초기 현금흐름 ${fmt(s.cf0)}${unitName()}에 이후 현금흐름의 현재가치 ${fmt(r.inflowPV)}${unitName()}를 더하면 순현재가치는 ${fmt(r.result)}${unitName()}입니다.</p><div class="formula-box">NPV = CF₀ + Σ CF<sub>t</sub> / (1 + i)<sup>t</sup><br><small>i = ${pct(r.i)}% / ${s.py===12?'월':'년'}</small></div><p class="insight-small">NPV &gt; 0은 입력한 할인율을 초과하는 가치 창출을 뜻합니다. 회계상 이익이나 단순한 현금 수익과는 다릅니다. F는 동일한 금액이 다음 기간에도 연속 발생하는 횟수입니다.</p><div class="sign-legend"><span><i class="legend-dot"></i>− 현금 유출</span><span><i class="legend-dot positive"></i>+ 현금 유입</span></div>`;
 }
 }catch(e){lastResult=null;$('#result-panel').innerHTML=commonHead('CHECK YOUR INPUT')+`<div class="result-error" role="status"><h3>입력을 한 번 확인해 주세요.</h3><p>${e.message}</p></div>`;$('#key-guide').innerHTML='<p class="error-placeholder">유효한 입력을 완료하면 키 순서가 표시됩니다.</p>';$('#interpretation').innerHTML='<p class="error-placeholder">입력값과 단위를 확인하면 해석이 표시됩니다.</p>';}
}
function npvChart(r,s){const vals=[s.cf0,...r.rows.slice(0,12).map(x=>x.amount)],max=Math.max(...vals.map(Math.abs),1),w=320/vals.length;return `<div class="result-section-label">CASH FLOWS · ${s.py===12?'MONTH':'YEAR'}</div><svg viewBox="0 0 360 110" class="timeline-svg" role="img" aria-label="초기 투자와 이후 현금흐름 차트. ${r.periods>12?'처음 12기간 표시.':''}"><line x1="12" x2="350" y1="55" y2="55" stroke="#55745e"/>${vals.map((v,j)=>{const x=20+w*j,h=Math.abs(v)/max*35;return `<rect x="${x}" y="${v>=0?55-h:55}" width="${Math.max(3,w*.45)}" height="${Math.max(1,h)}" rx="2" fill="${v>=0?'#c4dba6':'#d49b77'}"/><text x="${x+w*.22}" y="106" fill="#a1b995" text-anchor="middle" font-size="9">${j}</text>`}).join('')}</svg>${r.periods>12?'<div class="note-badge">차트에는 처음 12기간만 표시됩니다.</div>':''}`;}
const keys=arr=>`<div class="keys">${arr.map((k,j)=>`${j?'<span class="key-arrow">›</span>':''}<kbd class="${['CPT','ENTER','CLR TVM','CLR WORK'].includes(k)?'accent':''}">${k}</kbd>`).join('')}</div>`;
function step(n,label,rows,note=''){return `<div class="key-step"><span class="step-index">${n}</span><div><div class="step-heading">${label}</div>${rows.map(keys).join('')}${note?`<p class="step-note">${note}</p>`:''}</div></div>`;}
const signedKeys=x=>x<0?[raw(Math.abs(x)),'+/−']:[raw(x)];
function renderTvmGuide(r,s){
 const v=r.values;let inputRows=[];
 for(const [k,key] of [['n','N'],['rate','I/Y'],['pv','PV'],['pmt','PMT'],['fv','FV']])if(k!==s.solve)inputRows.push([...signedKeys(k==='rate'?r.nominal*100:v[k]),key]);
 $('#key-guide').innerHTML=step(1,'TVM 메모리 초기화',[['2nd','FV (CLR TVM)']],'N·I/Y·PV·PMT·FV를 지웁니다. P/Y·C/Y는 유지됩니다.')+step(2,`연 빈도 설정 · P/Y ${s.py}, C/Y ${s.cy}`,[['2nd','I/Y (P/Y)',String(s.py),'ENTER'],['↓',String(s.cy),'ENTER','2nd','CPT (QUIT)']],'P/Y 입력 후 C/Y를 설정합니다. 입력 이율은 연 명목으로 변환해 안내합니다.')+step(3,`지급 시점 확인 · ${s.bgn?'BGN (기간 초)':'END (기간 말)'}`,[['2nd','PMT (BGN)']],[`화면이 ${s.bgn?'BGN':'END'}인지 확인. 다르면 [2nd] [ENTER (SET)]로 한 번 전환한 후, [2nd] [CPT (QUIT)]로 나옵니다.`])+step(4,'알고 있는 네 변수를 입력',inputRows,s.solve!=='rate'&&s.rateType!=='nominal'?`입력 이율을 연 명목 ${pct(r.nominal)}%로 환산했습니다. 키 안내에는 더 긴 정밀도를 사용합니다.`:'금액은 선택한 단위 그대로 입력합니다. 음수는 숫자 다음 +/−.')+step(5,'계산할 변수를 호출',[['CPT',{pv:'PV',fv:'FV',pmt:'PMT',n:'N',rate:'I/Y'}[s.solve]]])+`<div class="key-summary">[2nd]와 다음 키는 차례로 누릅니다. 괄호는 키 위의 보조 기능입니다. 표시는 반올림되어도 입력 값은 유지됩니다.</div>`;
}
function renderTvmInsight(r,s){
 const u=unitName(),n=fmt(r.n,2),freq=s.py===12?'매월':s.py===1?'매년':`연 ${s.py}회`,v=r.values;
 const titles={pv:'미래의 현금흐름을,<br>오늘의 가치로.',fv:'오늘의 돈이,<br>시간을 만나 자랍니다.',pmt:'목표와 기간을,<br>한 번의 지급액으로.',n:'목표에 필요한 시간,<br>기간 수로 확인하세요.',rate:'현금흐름이 말하는,<br>연 명목이율입니다.'};
 let text={pv:`매회 현금흐름 ${fmt(s.pmt)}${u}, 마지막 현금흐름 ${fmt(s.fv)}${u}를 ${n}기간에 걸쳐 할인한 값입니다. 현재가치의 크기는 ${fmt(Math.abs(r.result))}${u}이며, 이를 맞추는 현재 현금흐름의 부호는 ${r.result<0?'음수':'양수'}입니다.`,fv:`현재 ${fmt(s.pv)}${u}와 매회 ${fmt(s.pmt)}${u}의 현금흐름을 반영하면, ${n}기간 후 ${fmt(r.result)}${u}가 됩니다.`,pmt:`현재 ${fmt(s.pv)}${u}에서 시작해 ${n}기간 후 ${fmt(s.fv)}${u}를 맞추려면, ${freq} ${fmt(r.result)}${u}의 현금흐름이 필요합니다.`,n:`이 조건을 만족하는 기간은 ${n}회, 약 ${fmt(r.n/s.py,4)}년입니다. 실제 지급 횟수는 ${Math.ceil(r.n)}회로 올림하고 마지막 지급액을 조정할 수 있습니다.`,rate:`이 현금흐름의 연 명목이율은 ${pct(r.result)}%입니다. 같은 조건의 한 기간 이율은 ${pct(r.i)}%, 연 실효이율은 ${pct(r.ear)}%입니다.`}[s.solve];
 $('#interpretation').innerHTML=`<h4 class="insight-title">${titles[s.solve]}</h4><p class="insight-copy">${text}</p><div class="formula-box">PV(1+i)<sup>N</sup> + PMT × (1+i)<sup>b</sup><br>× [(1+i)<sup>N</sup> − 1] / i + FV = 0<br><small>i = ${pct(r.i)}% · b = ${s.bgn?1:0}</small></div><p class="insight-small">${s.py===s.cy?`P/Y = C/Y이므로, 연 명목이율 ÷ ${s.py} = 한 기간 이율입니다.`:`P/Y ${s.py}와 C/Y ${s.cy}가 다르므로 단순 나눗셈 대신 복리의 등가 이율을 사용합니다.`} N은 ${n}회입니다. ${r.i===0?'이율 0%에서는 연금계수를 N으로 계산합니다.':''}</p><div class="sign-legend"><span><i class="legend-dot"></i>− 지출·납입</span><span><i class="legend-dot positive"></i>+ 수령·회수</span></div>`;
}
function renderAprGuide(r,s){
 const nom=s.direction==='nominal';
 $('#key-guide').innerHTML=step(1,'이율 환산 워크시트 열기',[['2nd','2 (ICONV)'],['2nd','CE/C (CLR WORK)']],'NOM 화면에서 시작합니다. C/Y도 아래에서 직접 설정합니다.')+step(2,nom?'NOM에 연 명목이율 입력':'EFF로 이동해 연 실효이율 입력',[[...(nom?[]:['↓']),...signedKeys(s.rate),'ENTER']])+step(3,`C/Y에 연 복리 횟수 ${s.cy} 입력`,[[...(nom?['↓','↓']:['↓']),String(s.cy),'ENTER']])+step(4,nom?'EFF를 계산':'NOM을 계산',[[...(nom?['↑']:['↑','↑']),'CPT']])+`<div class="key-summary">ICONV는 연 명목 ↔ 연 실효 이율 환산입니다. TVM의 지급 횟수 N은 여기서 사용하지 않습니다.</div>`;
}
function renderNpvGuide(r,s){
 let rows=[];s.flows.forEach((f,j)=>{rows.push([...signedKeys(f.amount),'ENTER','↓']);rows.push([String(f.frequency),'ENTER',...(j<s.flows.length-1?['↓']:[])]);});
 $('#key-guide').innerHTML=step(1,'현금흐름 워크시트 초기화',[['CF'],['2nd','CE/C (CLR WORK)']])+step(2,'CF₀ · 초기 현금흐름 입력',[[...signedKeys(s.cf0),'ENTER','↓']])+step(3,'C01 → F01 → C02 → F02 순서',rows,'각 C는 금액, 다음 F는 그 금액이 연속되는 기간 수입니다. C 입력 후 ↓, F 입력 후 ↓로 다음 C로 이동합니다.')+step(4,`NPV의 I에 기간 할인율 ${pct(r.i)}% 입력`,[['NPV',...signedKeys(r.i*100),'ENTER','↓','CPT']],'NPV 워크시트의 I는 한 현금흐름 기간 이율입니다. P/Y로 자동 환산되지 않습니다.')+`<div class="key-summary">CF₀ 다음 현금흐름은 1기간 말부터 시작합니다. 중간에 현금흐름이 없으면 금액 0도 해당 횟수만큼 입력하세요.</div>`;
}
function renderExamples(){const list=examples.filter(e=>e.mode===mode);$('#example-cards').innerHTML=list.map(e=>`<button type="button" class="example-card" data-example="${e.id}"><span class="example-category">${modes[e.mode].tag} · EXAMPLE</span><strong>${e.title}</strong><p>${e.caption}</p>${exampleStories[e.id]?`<p class="example-question">${exampleStories[e.id].goal}</p>`:''}<span class="example-answer">${e.answer}</span><span class="card-arrow">↗</span></button>`).join('');}
function render(){renderNav();$('#mode-title').textContent=modes[mode].title;$('#mode-index').textContent=modes[mode].index;$('#mode-tag').textContent=modes[mode].tag;$('#example-note').textContent=selectedExample?`→ 학습 예제 · ${examples.find(x=>x.id===selectedExample)?.title||''}`:'';$('#problem-details').innerHTML=storyCard(selectedExample);renderForm();renderResult();renderExamples();}
function switchMode(m){mode=m;selectedExample=null;render();}
$('#input-form').addEventListener('input',e=>{if(e.target.tagName==='INPUT'){readForm();selectedExample=null;$('#example-note').textContent='';const status=$('.scenario-status');if(status)status.textContent='입력값 수정 중 · 아래는 원래 예제 조건';renderResult();}});
$('#input-form').addEventListener('change',e=>{if(e.target.tagName==='SELECT'){readForm();selectedExample=null;$('#example-note').textContent='';const status=$('.scenario-status');if(status)status.textContent='입력값 수정 중 · 아래는 원래 예제 조건';renderForm();renderResult();}});
$('#input-form').addEventListener('submit',e=>{e.preventDefault();readForm();renderResult();if(matchMedia('(max-width:850px)').matches)$('#result-panel').scrollIntoView({behavior:matchMedia('(prefers-reduced-motion:reduce)').matches?'instant':'smooth',block:'start'});});
$('#reset').addEventListener('click',()=>{states[mode]=structuredClone(defaults[mode]);selectedExample=null;render();});
document.addEventListener('click',e=>{const b=e.target.closest('button');if(!b)return;if(b.dataset.mode){switchMode(b.dataset.mode);}else if(b.hasAttribute('data-help')){$('#help-dialog').showModal();}else if(b.dataset.close){document.getElementById(b.dataset.close).close();}else if(b.id==='open-method'){$('#method-dialog').showModal();}else if(b.dataset.timing){readForm();selectedExample=null;$('#example-note').textContent='';const status=$('.scenario-status');if(status)status.textContent='입력값 수정 중 · 아래는 원래 예제 조건';states[mode].bgn=b.dataset.timing==='bgn';renderForm();renderResult();}else if(b.id==='add-flow'){readForm();if(states.npv.flows.length<24){states.npv.flows.push({amount:0,frequency:1});renderForm();renderResult();$(`[name="flow-${states.npv.flows.length-1}"]`).focus();}}else if(b.dataset.remove!==undefined){readForm();states.npv.flows.splice(+b.dataset.remove,1);renderForm();renderResult();}else if(b.dataset.example){const example=examples.find(x=>x.id===b.dataset.example);mode=example.mode;states[mode]=structuredClone(example.data);selectedExample=example.id;render();$('.workspace-title').scrollIntoView({behavior:matchMedia('(prefers-reduced-motion:reduce)').matches?'instant':'smooth',block:'start'});}});
for(const dialog of document.querySelectorAll('dialog'))dialog.addEventListener('click',e=>{if(e.target===dialog){const rect=dialog.getBoundingClientRect();if(e.clientX<rect.left||e.clientX>rect.right||e.clientY<rect.top||e.clientY>rect.bottom)dialog.close();}});
render();
